/*
 * A166714  Number of reduced words of length n in Coxeter group on 41
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^12 = I.
 * https://oeis.org/A166714
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) generated by the rational G.f. Recurrence (derived from the
 *            denominator) a(n) = 39·a(n‑1) + ... + 39·a(n‑11) – 780·a(n‑12) +
 *            [n==12] The "+[n==12]" term comes from the numerator's t¹²
 *            coefficient (1)
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 6, u64 n <= 12, u128 n <= 24,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *cache = NULL;      /* cache of computed terms */
static size_t cache_len = 0;     /* current cache size */

/* Extend the cache up to index n, computing terms on first access. */
static void ensure_cache(idx_t n)
{
    if (cache_len > (size_t)n)
        return;

    size_t new_len = (size_t)n + 1;
    seq_t *tmp = (seq_t *)realloc(cache, new_len * sizeof(seq_t));
    if (!tmp)            /* allocation failure – caller will see garbage */
        return;
    cache = tmp;

    /* first 12 terms of the sequence */
    static const seq_t init[12] = {
        1ULL,                  /* a(0) */
        41ULL,                 /* a(1) */
        1640ULL,               /* a(2) */
        65600ULL,              /* a(3) */
        2624000ULL,            /* a(4) */
        104960000ULL,          /* a(5) */
        4198400000ULL,         /* a(6) */
        167936000000ULL,       /* a(7) */
        6717440000000ULL,      /* a(8) */
        268697600000000ULL,    /* a(9) */
        10747904000000000ULL, /* a(10) */
        429916160000000000ULL /* a(11) */
    };

    for (size_t i = cache_len; i < new_len; ++i)
    {
        if (i <= 11)                      /* copy the initial terms         */
        {
            cache[i] = init[i];
        }
        else                              /* recurrence for i >= 12         */
        {
            seq_t sum = 0;
            for (idx_t k = 1; k <= 11; ++k)
                sum += cache[i - k];
            seq_t term = 39 * sum - 780 * cache[i - 12];
            if (i == 12)                   /* extra +1 from the numerator     */
                term += 1;
            cache[i] = term;
        }
    }
    cache_len = new_len;
}

/* Public interface: a(n) for arbitrary n >= 0. */
seq_t a(idx_t n)
{
    ensure_cache(n);
    return cache[n];
}
